customers = pd.DataFrame({
    'customer_id': [1, 2, 3],
    'name': ['Asha', 'Ravi', 'Meera']
})
orders = pd.DataFrame({
    'customer_id': [1, 1, 2],
    'amount': [250, 400, 150]
})

# Inner join: only customers who ordered
result = customers.merge(orders, on='customer_id', how='inner')

# Left join: all customers, NaN where no order exists
result = customers.merge(orders, on='customer_id', how='left')
